// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native bezier math (De Casteljau) for tip riding and path generation

const { fontFamily: interFamily } = loadInter();



export type MortgageSpikeProps = Record<string, any>;

// Math helper for De Casteljau interpolation
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

const MortgageSpike: React.FC<MortgageSpikeProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 4,
  graphColor = "#ff2a2a",
  dollarColor = "#cc0000",
  houseColor = "#ffffff",
  glowIntensity = 50,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Animation timing
  const totalFrames = durationInSeconds * fps;
  const curveEndFrame = totalFrames * 0.85; // Leave 15% for the climax/shake
  
  // The core graph progress (accelerates exponentially)
  const t = interpolate(frame, [15, curveEndFrame], [0, 1], {
    easing: Easing.in(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Fade in elements smoothly at the start
  const initialFade = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Curve definition (Cubic Bezier for a sharp hockey-stick rise)
  const p0x = width * 0.1;
  const p0y = height * 0.85;
  const p1x = width * 0.5;
  const p1y = height * 0.85;
  const p2x = width * 0.8;
  const p2y = height * 0.75;
  const p3x = width * 0.85;
  const p3y = height * 0.2;

  // De Casteljau subdivision to get the partial path and EXACT tip position per frame
  const ax = lerp(p0x, p1x, t); const ay = lerp(p0y, p1y, t);
  const bx = lerp(p1x, p2x, t); const by = lerp(p1y, p2y, t);
  const cx = lerp(p2x, p3x, t); const cy = lerp(p2y, p3y, t);

  const dx = lerp(ax, bx, t); const dy = lerp(ay, by, t);
  const ex = lerp(bx, cx, t); const ey = lerp(by, cy, t);

  const tipX = lerp(dx, ex, t); const tipY = lerp(dy, ey, t);

  // Partial path drawn up to current t
  const partialD = `M ${p0x} ${p0y} C ${ax} ${ay}, ${dx} ${dy}, ${tipX} ${tipY}`;

  // Calculate tangent angle for the arrowhead
  const tangentX = ex - dx;
  const tangentY = ey - dy;
  const angle = t > 0.01 ? Math.atan2(tangentY, tangentX) * (180 / Math.PI) : 0;

  // Screen shake logic (triggers aggressively at the end of the curve)
  const shakeIntensity = interpolate(t, [0.9, 1.0], [0, 25 * s], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const shakeX = shakeIntensity > 0 ? (random(`x-${frame}`) - 0.5) * 2 * shakeIntensity : 0;
  const shakeY = shakeIntensity > 0 ? (random(`y-${frame}`) - 0.5) * 2 * shakeIntensity : 0;

  // Pre-calculate fixed positions for the dollar stacks along the curve
  const stackPositions = useMemo(() => {
    // Defines the 't' intervals where stacks will appear
    const intervals = [0.15, 0.35, 0.55, 0.7, 0.82, 0.92, 0.99];
    
    return intervals.map(st => {
      // Calculate static position for this stack column on the final curve
      const sa = lerp(p0x, p1x, st); const s_ay = lerp(p0y, p1y, st);
      const sb = lerp(p1x, p2x, st); const s_by = lerp(p1y, p2y, st);
      const sc = lerp(p2x, p3x, st); const s_cy = lerp(p2y, p3y, st);
      const sd = lerp(sa, sb, st); const s_dy = lerp(s_ay, s_by, st);
      const se = lerp(sb, sc, st); const s_ey = lerp(s_by, s_cy, st);
      const stX = lerp(sd, se, st); const stY = lerp(s_dy, s_ey, st);
      
      return { st, x: stX, y: stY };
    });
  }, [p0x, p1x, p2x, p3x, p0y, p1y, p2y, p3y]);

  const houseSize = 140 * s;
  const dollarSpacing = 42 * s;
  const glowBlur = (glowIntensity / 100) * 30 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      
      {/* Background radial glow that intensifies at the peak */}
      <div style={{
        position: "absolute",
        top: p3y - 300 * s,
        left: p3x - 300 * s,
        width: 600 * s,
        height: 600 * s,
        background: `radial-gradient(circle, ${graphColor}44 0%, transparent 70%)`,
        opacity: interpolate(t, [0.7, 1], [0, 1]),
        transition: "none"
      }} />

      {/* Main Shaking Wrapper */}
      <div style={{ 
        position: "absolute", 
        width: "100%", 
        height: "100%", 
        transform: `translate(${shakeX}px, ${shakeY}px)`,
        transition: "none",
        opacity: initialFade
      }}>
        
        {/* Dollar Stacks Layer */}
        {stackPositions.map((stack, colIdx) => {
          const stackHeight = p0y - stack.y;
          // Calculate how many dollars fit under this point on the curve
          const numDollars = Math.max(0, Math.floor(stackHeight / dollarSpacing));
          
          return (
            <div key={`col-${colIdx}`} style={{ position: 'absolute', left: stack.x, bottom: height - p0y, transition: "none" }}>
              {Array.from({ length: numDollars }).map((_, i) => {
                const dollarYOffset = i * dollarSpacing;
                
                // Dollars animate in sequentially as the main line approaches this stack's 't'
                const dollarStartT = Math.max(0, stack.st - 0.15 + (i / Math.max(1, numDollars)) * 0.1);
                const dollarScale = interpolate(t, [dollarStartT, dollarStartT + 0.05], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: Easing.back(1.5)
                });
                
                return (
                  <div key={`dollar-${colIdx}-${i}`} style={{
                    position: 'absolute',
                    bottom: dollarYOffset,
                    transform: `translateX(-50%) scale(${dollarScale})`,
                    color: dollarColor,
                    fontSize: `${50 * s}px`,
                    fontWeight: 900,
                    textShadow: `
                      1px 1px 0 #550000, 
                      2px 2px 0 #550000, 
                      3px 3px 0 #550000, 
                      4px 4px 0 #440000,
                      0 0 ${10 * s}px ${graphColor}
                    `,
                    transition: "none"
                  }}>
                    $
                  </div>
                );
              })}
            </div>
          );
        })}

        {/* Core SVG Graphics (Lines, Dots, House, Arrow) */}
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} style={{ position: 'absolute', overflow: 'visible', transition: "none" }}>
          
          <defs>
            <filter id="heavyGlow" x="-50%" y="-50%" width="200%" height="200%">
              <feGaussianBlur stdDeviation={glowBlur} result="coloredBlur"/>
              <feMerge>
                <feMergeNode in="coloredBlur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
            <filter id="lightGlow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation={glowBlur * 0.3} result="blur"/>
              <feMerge>
                <feMergeNode in="blur"/>
                <feMergeNode in="SourceGraphic"/>
              </feMerge>
            </filter>
          </defs>

          {/* Under-glow for the main line */}
          <path 
            d={partialD} 
            fill="none" 
            stroke={graphColor} 
            strokeWidth={25 * s} 
            strokeLinecap="round" 
            opacity={0.3}
            filter="url(#heavyGlow)"
            style={{ transition: "none" }} 
          />
          
          {/* Main crisp line */}
          <path 
            d={partialD} 
            fill="none" 
            stroke="#ffffff" 
            strokeWidth={8 * s} 
            strokeLinecap="round" 
            filter="url(#lightGlow)"
            style={{ transition: "none" }} 
          />

          {/* Data Points (Dots on the line) */}
          {stackPositions.map((stack, i) => {
            const dotScale = interpolate(t, [stack.st - 0.05, stack.st], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.quad) });
            return (
              <g key={`dot-${i}`} transform={`translate(${stack.x}, ${stack.y}) scale(${dotScale})`} style={{ transition: "none" }}>
                <circle r={10 * s} fill="#ffffff" filter="url(#heavyGlow)" />
                <circle r={6 * s} fill="#ffffff" />
              </g>
            );
          })}

          {/* Arrowhead riding the tip */}
          <g 
            transform={`translate(${tipX}, ${tipY}) rotate(${angle})`} 
            style={{ transition: "none" }}
          >
            <polygon 
              points={`0,${-15 * s} ${25 * s},0 0,${15 * s}`} 
              fill="#ffffff" 
              filter="url(#heavyGlow)" 
            />
          </g>

          {/* House Element riding above the tip */}
          <g transform={`translate(${tipX}, ${tipY - houseSize/2 - (40 * s)})`} style={{ transition: "none" }}>
            
            {/* House Downward Light Streaks */}
            {Array.from({ length: 5 }).map((_, i) => {
              const streakOpacity = interpolate(t, [0.5, 1], [0, 0.6], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              const xPos = (i - 2) * (20 * s);
              const streakLength = interpolate(t, [0.5, 1], [0, 150 * s], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              return (
                <rect
                  key={`streak-${i}`}
                  x={xPos - (3 * s)}
                  y={houseSize / 2}
                  width={6 * s}
                  height={streakLength}
                  fill={houseColor}
                  opacity={streakOpacity}
                  filter="url(#heavyGlow)"
                  style={{ transition: "none" }}
                />
              );
            })}

            {/* The House Icon */}
            <g transform={`translate(${-houseSize/2}, ${-houseSize/2}) scale(${houseSize / 100})`} filter="url(#heavyGlow)" style={{ transition: "none" }}>
              {/* Roof */}
              <path d="M 50 0 L 0 45 L 10 45 L 10 100 L 90 100 L 90 45 L 100 45 Z" fill={houseColor} />
              {/* Chimney */}
              <path d="M 75 25 L 75 10 L 88 10 L 88 35 Z" fill={houseColor} />
              
              {/* Windows (punched out via drawing rectangles over the base house but coloured as background) */}
              {/* Top Left Window */}
              <rect x="25" y="55" width="20" height="15" fill={backgroundColor} opacity={0.9} />
              {/* Top Right Window */}
              <rect x="55" y="55" width="20" height="15" fill={backgroundColor} opacity={0.9} />
              {/* Bottom Left Window */}
              <rect x="25" y="75" width="20" height="15" fill={backgroundColor} opacity={0.9} />
              {/* Bottom Right Window */}
              <rect x="55" y="75" width="20" height="15" fill={backgroundColor} opacity={0.9} />
            </g>
          </g>

        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default MortgageSpike;